-- Disposable database only: apply bootstrap + migration first. All fixtures roll back.
BEGIN;
INSERT INTO auth.users(id) VALUES ('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003');
INSERT INTO public.profiles(id,role) VALUES ('00000000-0000-0000-0000-000000000001','admin'),('00000000-0000-0000-0000-000000000002','student'),('00000000-0000-0000-0000-000000000003','guardian');
DO $$
DECLARE i uuid; i2 uuid; i3 uuid; s uuid; s2 uuid; sess uuid; link uuid; again uuid; total integer; denied boolean;
BEGIN
  IF has_function_privilege('anon','public.confirm_intro_student_conversion(uuid,uuid)','EXECUTE') OR has_function_privilege('anon','public.revoke_intro_student_conversion(uuid,integer)','EXECUTE') THEN RAISE EXCEPTION 'Anonymous RPC granted'; END IF;
  IF has_table_privilege('authenticated','public.intro_student_conversions','INSERT') OR has_table_privilege('authenticated','public.intro_student_conversion_events','UPDATE') THEN RAISE EXCEPTION 'Direct writes granted'; END IF;
  INSERT INTO public.intro_clients(full_name) VALUES('QA trial') RETURNING id INTO i;
  INSERT INTO public.intro_clients(full_name) VALUES('QA trial second') RETURNING id INTO i2;
  INSERT INTO public.intro_clients(full_name) VALUES('QA no attendance') RETURNING id INTO i3;
  INSERT INTO public.students(full_name) VALUES('QA student') RETURNING id INTO s;
  INSERT INTO public.students(full_name) VALUES('QA student second') RETURNING id INTO s2;
  INSERT INTO public.sessions(start_at) VALUES(now()-interval '20 days') RETURNING id INTO sess;
  INSERT INTO public.bookings(intro_client_id,session_id,status) VALUES(i,sess,'attended'),(i2,sess,'attended'),(i3,sess,'reserved');
  INSERT INTO public.student_memberships(student_id,start_date,status,membership_origin) VALUES(s,current_date-10,'active','paid'),(s2,current_date-30,'expired','paid');
  PERFORM set_config('request.jwt.claim.sub','',true);
  BEGIN PERFORM public.confirm_intro_student_conversion(i,s); RAISE EXCEPTION 'Anonymous identity allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
  BEGIN PERFORM public.confirm_intro_student_conversion(i,s); RAISE EXCEPTION 'Student identity allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
  BEGIN PERFORM public.confirm_intro_student_conversion(i,s); RAISE EXCEPTION 'Guardian identity allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
  denied:=false; BEGIN PERFORM public.confirm_intro_student_conversion(i3,s); EXCEPTION WHEN raise_exception THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Unattended trial allowed'; END IF;
  denied:=false; BEGIN PERFORM public.confirm_intro_student_conversion(i,s2); EXCEPTION WHEN raise_exception THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Membership predating trial allowed'; END IF;
  UPDATE public.student_memberships SET start_date=current_date+1 WHERE student_id=s2;
  denied:=false; BEGIN PERFORM public.confirm_intro_student_conversion(i,s2); EXCEPTION WHEN raise_exception THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Future enrollment allowed'; END IF;
  UPDATE public.student_memberships SET start_date=current_date-10,membership_origin='gift' WHERE student_id=s2;
  denied:=false; BEGIN PERFORM public.confirm_intro_student_conversion(i,s2); EXCEPTION WHEN raise_exception THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Gift enrollment counted'; END IF;
  UPDATE public.student_memberships SET membership_origin='paid',status='cancelled' WHERE student_id=s2;
  denied:=false; BEGIN PERFORM public.confirm_intro_student_conversion(i,s2); EXCEPTION WHEN raise_exception THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Cancelled enrollment counted'; END IF;
  UPDATE public.student_memberships SET status='draft' WHERE student_id=s2;
  denied:=false; BEGIN PERFORM public.confirm_intro_student_conversion(i,s2); EXCEPTION WHEN raise_exception THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Draft enrollment counted'; END IF;
  UPDATE public.student_memberships SET status='active' WHERE student_id=s2;
  link:=public.confirm_intro_student_conversion(i,s);
  BEGIN PERFORM public.confirm_intro_student_conversion(i,s2); RAISE EXCEPTION 'Duplicate intro identity allowed'; EXCEPTION WHEN unique_violation THEN NULL; END;
  again:=public.confirm_intro_student_conversion(i,s);
  IF link<>again THEN RAISE EXCEPTION 'Confirmation not idempotent'; END IF;
  SELECT count(*) INTO total FROM public.intro_student_conversion_events WHERE conversion_id=link;
  IF total<>1 THEN RAISE EXCEPTION 'Idempotency duplicated audit'; END IF;
  BEGIN PERFORM public.confirm_intro_student_conversion(i2,s); RAISE EXCEPTION 'Duplicate student allowed'; EXCEPTION WHEN unique_violation THEN NULL; END;
  BEGIN PERFORM public.revoke_intro_student_conversion(link,99); RAISE EXCEPTION 'Stale version allowed'; EXCEPTION WHEN serialization_failure THEN NULL; END;
  PERFORM public.revoke_intro_student_conversion(link,1);
  BEGIN PERFORM public.revoke_intro_student_conversion(link,1); RAISE EXCEPTION 'Repeated revoke allowed'; EXCEPTION WHEN serialization_failure THEN NULL; END;
  again:=public.confirm_intro_student_conversion(i2,s);
  IF again=link THEN RAISE EXCEPTION 'Old audit record reused'; END IF;
  SELECT count(*) INTO total FROM public.intro_student_conversion_events WHERE conversion_id=link;
  IF total<>2 THEN RAISE EXCEPTION 'Revocation not audited'; END IF;
  -- Existing student deletion must remain possible, with both active and revoked audit preserved.
  DELETE FROM public.students WHERE id=s;
  IF EXISTS(SELECT 1 FROM public.intro_student_conversions WHERE id IN(link,again) AND student_id IS NOT NULL) THEN RAISE EXCEPTION 'Deleted student still referenced'; END IF;
  SELECT count(*) INTO total FROM public.intro_student_conversions WHERE id IN(link,again) AND student_name_at_confirmation='QA student';
  IF total<>2 THEN RAISE EXCEPTION 'Student deletion lost identity snapshots'; END IF;
  SELECT count(*) INTO total FROM public.intro_student_conversion_events WHERE conversion_id IN(link,again);
  IF total<>3 THEN RAISE EXCEPTION 'Student deletion lost conversion audit'; END IF;
END $$;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.intro_student_conversions) OR EXISTS(SELECT 1 FROM public.intro_student_conversion_events) THEN RAISE EXCEPTION 'Student sees admin identity links'; END IF; END $$;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
DO $$ BEGIN IF (SELECT count(*) FROM public.intro_student_conversions)<>2 THEN RAISE EXCEPTION 'Admin cannot inspect history'; END IF; END $$;
RESET ROLE;
ROLLBACK;
